import {detectLanguage,estimateReading} from './content-metrics.js';
export {detectLanguage,estimateReading} from './content-metrics.js';
import {text} from './knowledge.js';
export const CONTENT_SCHEMA='unbrainrot.content-batch';
export const CONTENT_SCHEMA_VERSION='1.0';
const https=value=>{try{const u=new URL(value);return u.protocol==='https:'&&!u.username&&!u.password?u.href:''}catch{return ''}};
export function videoMedia(raw={}){const d=raw.dimension||raw.media||raw.pages?.[0]?.dimension||{};let width=Number(d.width),height=Number(d.height);if(!Number.isFinite(width)||!Number.isFinite(height)||width<1||height<1||width>16384||height>16384)return {width:null,height:null,aspectRatio:null,orientation:'unknown'};if(Math.abs(Number(d.rotate)||0)%180===90)[width,height]=[height,width];return {width,height,aspectRatio:width/height,orientation:width>height?'landscape':width<height?'portrait':'square'}}
export function normalizeContent(raw){if(!raw||typeof raw.id!=='string'||!raw.id||raw.id.length>2048||!['video','article'].includes(raw.kind))throw Error('Invalid content record');const url=https(raw.url);if(!url)throw Error('Invalid content URL');const item={...raw,title:text(raw.title).slice(0,500),desc:text(raw.description??raw.desc??'').slice(0,2000),url,cover:https(raw.cover)};item.description=item.desc;item.language=detectLanguage(item);if(item.kind==='article'&&!item.reading)item.reading=estimateReading(item.contentText);item.media={type:item.kind==='video'?'video':'image',cover:item.cover,...(item.kind==='video'?videoMedia(raw):{width:null,height:null,aspectRatio:null,orientation:'unknown'})};return item}
export function createContentBatch(items,context={},options={}){const unique=new Map();for(const raw of items){try{const item=normalizeContent(raw);unique.set(item.id,item)}catch{}}return {schema:CONTENT_SCHEMA,schemaVersion:CONTENT_SCHEMA_VERSION,version:'1',batchId:options.batchId||crypto.randomUUID(),stage:options.stage||'collected',createdAt:options.createdAt||new Date().toISOString(),context:{...context},items:[...unique.values()],pagination:{page:options.page||context.page||1,hasMore:options.hasMore===true},decisions:options.decisions||[]}}
export function parseContentBatch(data){if(!data||data.schema!==CONTENT_SCHEMA||data.schemaVersion!==CONTENT_SCHEMA_VERSION||typeof data.batchId!=='string'||!['collected','rules','reviewed'].includes(data.stage)||!Array.isArray(data.items)||!data.pagination||!Number.isInteger(data.pagination.page)||typeof data.pagination.hasMore!=='boolean')throw Error('内容 JSON 格式不兼容');const ids=new Set();return {...data,items:data.items.map(x=>{if(ids.has(x.id))throw Error('内容 JSON 包含重复 ID');ids.add(x.id);return normalizeContent(x)})}}
